#!/bin/sh
# glycine: 1 annotations, legfed_v1_0 families.
# Generated by lis-autocontent populate-gcv. redis_loader runs this only while Redis
# is empty, saving after each load.

set -o errexit -o pipefail

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
inputs=/docker-entrypoint-initdb.d/gcv_inputs.py

echo Glycine/max/annotations/Wm82.gnm4.ann1.T8TQ
python -u "$inputs" chromosomes \
  https://data.legumeinfo.org/Glycine/max/genomes/Wm82.gnm4.4PTR/glyma.Wm82.gnm4.4PTR.genome_main.fna.gz.fai \
  "$work/chromosomes.gff3"
python -u -m redis_loader --load-type append gff \
  --genus Glycine \
  --species max \
  --strain Wm82 \
  --chromosome-gff "$work/chromosomes.gff3" \
  --gene-gff https://data.legumeinfo.org/Glycine/max/annotations/Wm82.gnm4.ann1.T8TQ/glyma.Wm82.gnm4.ann1.T8TQ.gene_models_main.gff3.gz \
  --gfa https://data.legumeinfo.org/Glycine/max/annotations/Wm82.gnm4.ann1.T8TQ/glyma.Wm82.gnm4.ann1.T8TQ.legfed_v1_0.M65K.gfa.tsv.gz
